import React, { useState } from 'react'

function Search() {
    const [query, setQuery] = useState('');
    const [sort, setSort] = useState('');
    const [sort_dir, setSort_dir] = useState('');
    const [results, setResults] = useState(null);
    const [loading, setLoading] = useState(false);
    const [currentIndex, setCurrentIndex] = useState(0);
    const [currentItemIndex, setCurrentItemIndex] = useState(0);

    const handleSearch = async () => {
        setLoading(true);
        setResults(null); // Clear previous results
        try {
          const response = await fetch(`http://127.0.0.1:8000/zalora/data?query=${query}&sort=${sort}&sort_dir=${sort_dir}`);
          const data = await response.json();
          setResults(data.items); // Set results after fetching
        } catch (error) {
          console.error('Search failed:', error);
        } finally {
          setLoading(false);
        }
      };


    return (
        <div>
            <input
                type="search"
                placeholder="Search product"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
            />
            <button onClick={handleSearch}>Click to search</button>

            {/* Loading state */}
            {loading && <p>Loading...</p>}

            {/* Display results after data is fetched */}
            {results && results.length > 0 && (
                <div>
                    <ul className="carousel">
                        {/* Loop through each product */}
                        {results.map((item, itemIndex) => (
                            <li key={itemIndex}>
                                <h2>{item.Name}</h2>

                                {/* Check if the item has ImageList */}
                                {item.ImageList && item.ImageList.length > 0 ? (
                                    <div>
                                        {/* Display a carousel for each item */}
                                        <div className="image-carousel">
                                            <img
                                                src={item.ImageList[0]}  // Always show the first image initially
                                                alt={item.Name}
                                                style={{ width: '300px', height: 'auto' }}
                                            />
                                            {/* Navigation buttons */}
                                            <div className="carousel-controls">
                                                <button onClick={() => {
                                                    const newIndex = item.ImageList.length === 1 ? 0 : (0 - 1 + item.ImageList.length) % item.ImageList.length;
                                                    setResults(results.map((result, index) => {
                                                        if (index === itemIndex) {
                                                            result.currentImageIndex = newIndex; 
                                                        }
                                                        return result;
                                                    }));
                                                }}>
                                                    Prev
                                                </button>
                                                <button onClick={() => {
                                                    const newIndex = item.ImageList.length === 1 ? 0 : (0 + 1) % item.ImageList.length;
                                                    setResults(results.map((result, index) => {
                                                        if (index === itemIndex) {
                                                            result.currentImageIndex = newIndex;
                                                        }
                                                        return result;
                                                    }));
                                                }}>
                                                    Next
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                ) : (
                                    <p>No images available for this product</p>
                                )}

                                <label className="itemname">{item.Name}</label>
                                <span className="price">{item.Price}</span>
                                <span className="brand">{item.Brand}</span>
                                <span className="seller">Zalora</span>
                                <span className="avg_rating">{item.ReviewStatistics.AvgRating}</span>
                            </li>
                        ))}
                    </ul>
                </div>
            )}
        </div>
    );
}

export default Search;
